	/** 
	 * updating a MedicalDevice.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a MedicalDevice." );

		StringBuilder msg = new StringBuilder( "Failed to update a MedicalDevice : " );        
		MedicalDevice entity = read();
		UpdateMedicalDeviceCommand command = generateUpdateCommand();
		command.setMedicalDeviceId(entity.getMedicalDeviceId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created MedicalDevice." );

			// for use later on...
			medicalDeviceId = entity.getMedicalDeviceId();

			MedicalDeviceService proxy = MedicalDeviceService.getMedicalDeviceInstance();  

			proxy.updateMedicalDevice( command ).get();

			LOGGER.info( "-- Successfully saved MedicalDevice - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + medicalDeviceId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a MedicalDevice.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created MedicalDevice." );

		MedicalDevice entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read MedicalDevice with id " + medicalDeviceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read MedicalDevice with id " + medicalDeviceId );

			throw e;
		}

		try{
			MedicalDeviceService.getMedicalDeviceInstance().delete( new DeleteMedicalDeviceCommand( entity.getMedicalDeviceId() ) ).get();
			LOGGER.info( "-- Successfully deleted MedicalDevice with id " + medicalDeviceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete MedicalDevice with id " + medicalDeviceId );

			throw e;
		}
	}

